331	func ensureCloneSession(cmd *cobra.Command) error {
332		// ENTIRE_TOKEN supplies a verbatim bearer with no refreshable session to
333		// probe; leave any failure, including a blank token, to the normal flow
334		// (renderCoreError still cleans the message). Match coreapi's presence-based
335		// env-token precedence so this precondition never probes a stored session.
336		if _, ok := os.LookupEnv(auth.EnvTokenVar); ok {
337			return nil
338		}
339		if insecureHTTPRequested(cmd) {
340			auth.EnableInsecureHTTP()
341		}
342		loginServer, probeErr := probeCloneSession(cmd.Context())
343		if probeErr == nil {
344			return nil // session usable
345		}
346		msg, isReauth := auth.ReauthMessage(probeErr)
347		if !isReauth {
348			// Transient (network/STS) failure — not a re-auth prompt. Let the normal
349			// command flow surface it in its own terms.
350			return probeErr
351		}
352		if !interactive.CanPromptInteractively() {
353			return errors.New(msg)
354		}
355		loggedIn, err := interactiveReauthLogin(cmd, loginServer, msg)
356		if err != nil {
357			return err
358		}
359		if !loggedIn {
360			return NewSilentError(errors.New(msg))
361		}
362		return nil
363	}
